<script setup lang="ts">
import {ref} from 'vue';
import {nicknameImages,nicknameImage,saveNicknameImage,resetNicknameImages} from '../app/localNicknameImages';
const name=ref(''),url=ref(''),message=ref(''),adding=ref(false),editing=ref(false);
function add(){const value=name.value.trim();if(!value||value.length>80){message.value='请填写角色在终端中显示的名字。';return;}name.value=value;url.value=nicknameImage(value);adding.value=false;editing.value=true;message.value='';}
function edit(nickname:string){name.value=nickname;url.value=nicknameImage(nickname);adding.value=false;editing.value=true;message.value='';}
function save(){try{saveNicknameImage(name.value,url.value);message.value=url.value.trim()?name.value+'的头像已保存到本机':'已恢复'+name.value+'的默认头像';editing.value=false;}catch(e){message.value=(e as Error).message;}}
function reset(){try{resetNicknameImages();editing.value=adding.value=false;name.value=url.value='';message.value='所有自定义昵称头像已重置，主要角色头像设置保留。';}catch{message.value='重置失败，请检查浏览器存储。';}}
</script>
<template><details class="pt-card"><summary>自定义角色头像</summary><p>给其他角色添加头像：新增角色 → 填写终端昵称 → 设置图片。</p><button type="button" @click="adding=true;editing=false;name='';message=''">＋ 新增头像角色</button><div v-if="adding"><label>要设置头像的角色叫什么？<input v-model="name" maxlength="80" placeholder="例如：哥哥、路人同学，需与终端显示名字一致" @keydown.enter.prevent="add"></label><button type="button" @click="add">下一步：设置头像</button><button type="button" @click="adding=false">取消</button></div><article v-if="editing" class="pt-card"><h3>为「{{name}}」设置头像</h3><div v-if="nicknameImage(name)" class="pt-avatar"><img :src="nicknameImage(name)" alt="当前头像" referrerpolicy="no-referrer"></div><label>粘贴图片链接（可选）<input v-model="url" type="url" placeholder="https://…，留空使用默认头像"></label><button type="button" @click="save">保存此角色头像</button><button type="button" @click="editing=false">取消</button></article><button v-for="(image,nickname) in nicknameImages()" :key="nickname" class="pt-row" type="button" @click="edit(String(nickname))"><span class="pt-avatar"><img :src="image" alt="角色头像" referrerpolicy="no-referrer"></span><strong>{{nickname}}</strong><span>编辑头像 ›</span></button><p v-if="!Object.keys(nicknameImages()).length">还没有自定义头像，点击“新增头像角色”开始。</p><button type="button" @click="reset">重置所有自定义头像</button><p role="status">{{message}}</p><small>仅保存在本机，不发送给模型。同名角色使用同一头像。</small></details></template>
